// src/components/Taxis/Pasajero.jsx
import { useEffect, useState, useCallback, useRef } from 'react';
import { Button, Typography, Box } from '@mui/material';
import io from 'socket.io-client';
import { useAuth0 } from '@auth0/auth0-react';
import { useNavigate } from 'react-router-dom';
import '../../styles/taxis.css';
import useGoogleMaps from '../../hooks/UseGoogleMaps.jsx';
import BottomSheet from '../BottomSheet.jsx';
import AcceptTrip from './AcceptTrip.jsx';
import taxiIcon from '../../assets/taxi_marker.png';
import FreeTripPasajero from './FreeTripPasajero.jsx';
import PreferencesModal from './PreferencesModal.jsx';
import AdeudoWarning from './AdeudoWarning.jsx';

const DEFAULT_FROM = { lat: 19.432608, lng: -99.133209 };
//const DEFAULT_TO = { lat: 19.432608, lng: -99.133209 };

const DEFAULT_PREFERENCES = {
  marca: '',
  nombre: '',
  modelo: '',
  puertas: '',
  charla: 'indiferente',
  musica: 'indiferente',
  tipo_musica: [],
  wifi: false,
  agua: false,
  cargador: false,
  snacks: false,
  portabici: false,
  accesibilidad: false,
  mascotas: false,
  fumadores: false,
  aire_acondicionado: false,
  rockola: false,
  ambiente_inclusivo: false,
  otro_genero: false,
};

const Pasajero = ({ onFoundDrivers = () => { } }) => {
  const { user } = useAuth0();
  const navigate = useNavigate();

  const [fromAddress, setFromAddress] = useState(() => {
    const raw = sessionStorage.getItem('from_address');
    if (!raw) return null;
    return JSON.parse(raw);
  });
  const [toAddress, setToAddress] = useState(() => {
    const raw = sessionStorage.getItem('to_address');
    if (!raw) return null;
    return JSON.parse(raw);
  });

  const [fromCoordinates, setFromCoordinates] = useState(() => {
    const raw = sessionStorage.getItem('from_coords');
    if (!raw) return null;
    return JSON.parse(raw);
  });
  const [toCoordinates, setToCoordinates] = useState(() => {
    const raw = sessionStorage.getItem('to_coords');
    if (!raw) return null;
    return JSON.parse(raw);
  });

  const [fromMarkerPosition, setFromMarkerPosition] = useState(null);
  const [toMarkerPosition, setToMarkerPosition] = useState(null);

  const [loadingSearch, setLoadingSearch] = useState(() => {
    try {
      const raw = sessionStorage.getItem('cancelar');
      if (!raw) return false;
      return JSON.parse(raw);
    } catch (e) {
      console.warn('[Pasajero] error leyendo estado de búsqueda desde sessionStorage:', e);
      return false;
    }
  });

  const [error, setError] = useState(null);
  const [googleMapsLoaded, setGoogleMapsLoaded] = useState(false);
  const [sheetState, setSheetState] = useState('collapsed');
  const [preferencesModalOpen, setPreferencesModalOpen] = useState(false);
  const [freeTripModalOpen, setFreeTripModalOpen] = useState(false);

  const [preferences, setPreferences] = useState(DEFAULT_PREFERENCES);
  const [passenger, setPassenger] = useState(null);
  const [preferencesSaving, setPreferencesSaving] = useState(false);
  const [paymentLabory, setPaymentLabory] = useState(false);
  const [freeTrip, setFreeTrip] = useState(null);
  const [isTraveling, setIsTraveling] = useState(false);
  const [debtsLoading, setDebtsLoading] = useState(false);
  const [debtsError, setDebtsError] = useState(null);
  const [debts, setDebts] = useState([]);

  const { mapRef, fromMarkerRef, toMarkerRef } = useGoogleMaps(
    fromCoordinates,
    setFromCoordinates,
    setFromMarkerPosition,
    toCoordinates,
    setToCoordinates,
    setToMarkerPosition,
    setFromAddress,
    setToAddress,
    setGoogleMapsLoaded,
    googleMapsLoaded,
  );

  const directionsRendererRef = useRef(null);
  const directionsServiceRef = useRef(null);

  // Socket ref
  const socketRef = useRef(null);

  // Offers state + refs to store marker/infoWindow objects without forcing re-render
  const [offers, setOffers] = useState([]); // [{ id, coordinates, price, timestamp }]
  const offersRef = useRef([]); // same objects + { marker, infoWindow }
  const pendingOffersRef = useRef([]); // offers received before map is ready

  useEffect(() => {
    try {
      sessionStorage.setItem('cancelar', JSON.stringify(loadingSearch));
      sessionStorage.setItem('from_address', JSON.stringify(fromAddress));
      sessionStorage.setItem('to_address', JSON.stringify(toAddress));
      sessionStorage.setItem('from_coords', JSON.stringify(fromCoordinates));
      sessionStorage.setItem('to_coords', JSON.stringify(toCoordinates));
    } catch (e) {
      console.warn('[Pasajero] error guardando estado de búsqueda en sessionStorage:', e);
    }
  }, [loadingSearch, fromAddress, toAddress, fromCoordinates, toCoordinates]);

  // Selected offer for modal
  const [selectedOffer, setSelectedOffer] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const strapiUrl = process.env.REACT_APP_STRAPI_URL || "";
  const strapiToken = process.env.REACT_APP_STRAPI_TOKEN || "";

  // Util: stringify safe
  const safeStringify = (obj, max = 2000) => {
    try {
      const s = JSON.stringify(obj, null, 2);
      return s.length > max ? s.slice(0, max) + '... (truncated)' : s;
    } catch (e) {
      return String(obj);
    }
  };

  // Helper to convert socket url ws -> http for fetch
  const socketUrlToHttp = (url = '') => {
    if (!url) return null;
    try {
      return url
        .replace(/^wss:\/\//i, 'https://')
        .replace(/^ws:\/\//i, 'http://');
    } catch (e) {
      return null;
    }
  };

  const normalizePreferences = useCallback((prefs = {}) => {
    const base = { ...DEFAULT_PREFERENCES, ...(prefs || {}) };
    return {
      ...base,
      marca: base.marca ?? '',
      nombre: base.nombre ?? '',
      modelo: base.modelo ?? '',
      puertas: base.puertas ?? '',
      charla: base.charla ?? 'indiferente',
      musica: base.musica ?? 'indiferente',
      tipo_musica: Array.isArray(base.tipo_musica)
        ? base.tipo_musica.filter(Boolean).map((item) => String(item).trim()).filter(Boolean)
        : typeof base.tipo_musica === 'string'
          ? base.tipo_musica.split(',').map((item) => item.trim()).filter(Boolean)
          : [],
      wifi: Boolean(base.wifi),
      agua: Boolean(base.agua),
      cargador: Boolean(base.cargador),
      snacks: Boolean(base.snacks),
      portabici: Boolean(base.portabici),
      accesibilidad: Boolean(base.accesibilidad),
      mascotas: Boolean(base.mascotas),
      fumadores: Boolean(base.fumadores),
      aire_acondicionado: Boolean(base.aire_acondicionado),
      rockola: Boolean(base.rockola),
      ambiente_inclusivo: Boolean(base.ambiente_inclusivo),
      otro_genero: Boolean(base.otro_genero),
    };
  }, []);

  const getUserData = useCallback(async () => {
    if (!user?.email || !strapiUrl) return;

    try {
      const url = `${strapiUrl}/api/users?filters[email][$eq]=${user.email}&populate=*`;
      const headers = { 'Content-Type': 'application/json' };
      if (strapiToken) {
        headers.Authorization = `Bearer ${strapiToken}`;
      }

      const response = await fetch(url, { headers });
      if (!response.ok) {
        throw new Error('No se pudo cargar el usuario');
      }
      const data = await response.json();

      const userData = Array.isArray(data) ? data[0] : null;
      if (!userData) {
        throw new Error("No se encontró usuario");
      }
      //console.log('[Pasajero] datos del usuario cargados:', userData);
      setPassenger(userData);
    } catch (err) {
      console.warn('[Pasajero] no se pudo cargar el usuario:', err);
    }
  }, [strapiToken, strapiUrl, user?.email]);

  const loadUserPreferences = useCallback(async () => {
    if (!user?.email || !strapiUrl) return;

    try {
      const url = `${strapiUrl}/api/configuraciones-usuarios?filters[email][$eq]=${user.email}&populate=*`;
      const headers = { 'Content-Type': 'application/json' };
      if (strapiToken) {
        headers.Authorization = `Bearer ${strapiToken}`;
      }

      const response = await fetch(url, { headers });
      if (!response.ok) {
        throw new Error('No se pudieron cargar las preferencias');
      }

      const userData = await response.json();
      const savedSettings = userData?.data?.[0]?.attributes?.configuraciones || {};
      const payLabory = userData?.data?.[0]?.attributes?.pago_labory || false;
      const freeTripStatus = userData?.data?.[0]?.attributes?.free_trip || false;
      const enViaje = userData?.data?.[0]?.attributes?.en_viaje || false;

      setPreferences(normalizePreferences(savedSettings));
      setPaymentLabory(payLabory);
      setFreeTrip(freeTripStatus);
      setIsTraveling(enViaje);
    } catch (err) {
      console.warn('[Pasajero] no se pudieron cargar preferencias del usuario:', err);
      setPreferences(DEFAULT_PREFERENCES);
    }
  }, [normalizePreferences, strapiToken, strapiUrl, user?.email]);

  useEffect(() => {
    if (freeTrip === 'disponible') setFreeTripModalOpen(true);
  }, [freeTrip]);

  // Cargar adeudos del pasajero
  useEffect(() => {
    const fetchDebts = async () => {
      if (!user?.email) return;
      setDebtsLoading(true);
      setDebtsError(null);
      try {
        // Preferir variable de entorno STRAPI si existe, sino usar localhost:33032
        const url = `${strapiUrl.replace(/\/$/, '')}/api/taxi-debts?filters[pasajero_email][$eq]=${user.email
          }&filters[pagado][$eq]=false&populate=*`;

        const resp = await fetch(url, {
          headers: {
            'Content-Type': 'application/json',
            ...(strapiToken ? { Authorization: `Bearer ${strapiToken}` } : {}),
          },
        });
        if (!resp.ok) throw new Error('Error consultando adeudos');
        const json = await resp.json();
        const items = (json && json.data) || [];
        setDebts(items);
      } catch (err) {
        console.warn('[Pasajero] error cargando adeudos:', err);
        setDebtsError(err && (err.message || String(err)));
      } finally {
        setDebtsLoading(false);
      }
    };

    fetchDebts();
  }, [user?.email]);

  const handleOpenRecentTrips = () => {
    navigate('/taxis/viajes/historial', { state: { role: 'pasajero' } });
  };

  const saveUserPreferences = async () => {
    if (!user?.email) return;

    setPreferencesSaving(true);
    try {
      const normalized = normalizePreferences(preferences);
      const headers = { 'Content-Type': 'application/json' };
      if (strapiToken) {
        headers.Authorization = `Bearer ${strapiToken}`;
      }

      const findUrl = `${strapiUrl}/api/configuraciones-usuarios?filters[email][$eq]=${user.email}&populate=*`;
      const findResponse = await fetch(findUrl, { headers });
      const findData = await findResponse.json();
      const existing = findData?.data?.[0];
      const body = {
        data: {
          email: user.email,
          configuraciones: normalized,
          pago_labory: paymentLabory
        },
      };

      const endpoint = existing?.id
        ? `${strapiUrl}/api/configuraciones-usuarios/${existing.id}`
        : `${strapiUrl}/api/configuraciones-usuarios`;
      const method = existing?.id ? 'PUT' : 'POST';

      const response = await fetch(endpoint, {
        method,
        headers,
        body: JSON.stringify(body),
      });

      if (!response.ok) {
        const text = await response.text();
        throw new Error(text || 'No se pudieron guardar las preferencias');
      }

      setPreferencesModalOpen(false);
    } catch (err) {
      console.error('[Pasajero] error guardando preferencias:', err);
      setError(err.message || 'No se pudieron guardar las preferencias');
    } finally {
      setPreferencesSaving(false);
    }
  };

  const getSheetContent = () => {
    if (loadingSearch) {
      return (
        <>
          <Typography variant='h6'>Buscando conductores...</Typography>
          <Typography>
            Estamos buscando taxis cercanos. Por favor espera.
          </Typography>
          {sheetState === 'full' && (
            <Button
              variant='outlined'
              color='secondary'
              onClick={cancelarBusqueda}
              sx={{ mt: 2 }}
            >
              Cancelar búsqueda
            </Button>
          )}
        </>
      );
    }
    if (offers.length > 0) {
      return (
        <>
          <Typography variant='h6'>
            Ofertas disponibles ({offers.length})
          </Typography>
          <Typography>
            Hay conductores cerca. Expande para ver detalles y aceptar.
          </Typography>
          {sheetState === 'full' && (
            <Box sx={{ mt: 1 }}>
              {offers.map((offer) => (
                <Button
                  key={offer.id}
                  variant='contained'
                  size='small'
                  onClick={() => {
                    setSelectedOffer(offer);
                    setIsModalOpen(true);
                  }}
                  sx={{ m: 0.5 }}
                >
                  Oferta ${offer.price}
                </Button>
              ))}
            </Box>
          )}
        </>
      );
    }
    return (
      <>
        <Typography variant='h6'>Planifica tu viaje</Typography>
        <Typography>
          Ingresa origen y destino y presiona "Buscar Conductores".
        </Typography>
      </>
    );
  };

  // Crear marker + infoWindow para una oferta
  const createMarkerForOffer = useCallback(
    (offer) => {
      if (!mapRef || !mapRef.current || !window.google) {
        // guardar en pendientes si el mapa no está listo
        pendingOffersRef.current.push(offer);
        return;
      }

      try {
        const {
          id,
          coordinates,
          price,
          travelId,
          driverId,
          driverEmail,
          travel,
          driverRating
        } = offer;

        // Evitar duplicados: si ya existe un marker con este id, no crear otro
        if (offersRef.current.some((o) => o.id === id)) {
          return;
        }

        const position = new window.google.maps.LatLng(
          coordinates.lat,
          coordinates.lng,
        );

        // Marker
        const marker = new window.google.maps.Marker({
          position,
          map: mapRef.current,
          icon: {
            url: taxiIcon,
            scaledSize: new window.google.maps.Size(20, 40),
          },
          title: `Oferta $${price}`,
        });

        // InfoWindow pequeño (recuadro) que aparece por defecto
        const infoContent = `
          <div id="offer-info-${id}" style="font-family: Arial, sans-serif; font-size:13px;">
            <div style="font-weight:600; margin-bottom:4px;">Oferta: $${price}</div>
            <div style="font-size:12px; color:#555;">Click para ver opciones</div>
          </div>
        `;

        const infoWindow = new window.google.maps.InfoWindow({
          content: infoContent,
          position,
        });

        // Abrir infoWindow automáticamente
        infoWindow.open(mapRef.current, marker);

        // Aplicar estilos al "globito" amarillo cuando el DOM del InfoWindow esté listo
        window.google.maps.event.addListener(infoWindow, 'domready', () => {
          try {
            const contentEl = document.getElementById(`offer-info-${id}`);
            if (contentEl) {
              contentEl.style.background = '#fff200'; // amarillo del branding
              contentEl.style.color = '#111';
              contentEl.style.padding = '4px 5px';
              contentEl.style.borderRadius = '10px';
              contentEl.style.boxShadow = '0 6px 16px rgba(0,0,0,0.18)';
              contentEl.style.minWidth = '140px';
              contentEl.style.textAlign = 'left';
            }

            // Intentamos suavizar/ocultar el fondo por defecto del InfoWindow para que se vea solo tu chip
            const iwOuter = document.querySelector('.gm-style-iw');
            if (iwOuter) {
              // Hacer transparente el contenedor principal
              iwOuter.style.background = 'transparent';
              // Normalmente, el sibling anterior contiene sombras/fondos; lo ocultamos
              const iwBackground = iwOuter.previousElementSibling;
              if (iwBackground) iwBackground.style.display = 'none';
            }
          } catch (errSty) {
            console.warn(
              '[Pasajero] fallo aplicando estilos InfoWindow:',
              errSty,
            );
          }
        });

        // Listener en marker: al click abrir modal y seleccionar oferta
        const markerClickListener = marker.addListener('click', () => {
          setSelectedOffer(
            { id, travelId, coordinates, price, driverId, driverEmail, travel, driverRating }
          );
          setIsModalOpen(true);
        });

        // También añadir listener para el contenido del InfoWindow (domready)
        const domReadyListener = window.google.maps.event.addListener(
          infoWindow,
          'domready',
          () => {
            const elem = document.getElementById(`offer-info-${id}`);
            if (elem) {
              // hacer que click en el recuadro abra modal
              elem.style.cursor = 'pointer';
              if (!elem._hasClick) {
                elem.addEventListener('click', () => {
                  setSelectedOffer(
                    { id, travelId, coordinates, price, driverId, driverEmail, travel, driverRating }
                  );
                  setIsModalOpen(true);
                });
                elem._hasClick = true;
              }
            }
          },
        );

        // guardar en refs
        offersRef.current.push({
          ...offer,
          marker,
          infoWindow,
          _listeners: { markerClickListener, domReadyListener },
        });
      } catch (e) {
        console.warn('[Pasajero] error creando marker para oferta', e);
      }
    },
    [mapRef],
  );

  const removeAllOfferMarkers = useCallback(() => {
    if (offersRef.current.length === 0) {
      setOffers([]);
      return;
    }

    offersRef.current.forEach((offer) => {
      try {
        if (offer.infoWindow) offer.infoWindow.close();
        if (offer.marker) offer.marker.setMap(null);
      } catch (e) {
        console.warn('[Pasajero] error removiendo marker de oferta:', e);
      }
    });

    offersRef.current = [];
    setOffers([]);
  }, []);

  const getTravelOffers = useCallback(async () => {
    if (!strapiUrl || !user?.email) {
      removeAllOfferMarkers();
      setOffers([]);
      return;
    }

    try {
      removeAllOfferMarkers();
      pendingOffersRef.current = [];

      const url = `${strapiUrl.replace(/\/$/, '')}/api/viaje-ofertas?filters[user_email][$eq]=${user.email}&populate=*`;

      const res = await fetch(url, {
        headers: {
          'Content-Type': 'application/json',
          ...(strapiToken ? { Authorization: `Bearer ${strapiToken}` } : {}),
        },
      });

      if (!res.ok) {
        throw new Error(`Error cargando ofertas (${res.status})`);
      }

      const json = await res.json();
      const offersData = Array.isArray(json?.data) ? json.data : [];

      const normalizedOffers = offersData.reduce((acc, offer) => {
        const normalizedOffer = {
          id: offer.id,
          travelId: offer.attributes?.viaje?.data?.attributes?.travelid,
          travel: offer.attributes?.viaje?.data?.attributes,
          coordinates: offer.attributes?.coordenadas,
          price: offer.attributes?.precio_sugerido,
          driverId: offer.attributes?.conductor?.data?.id,
          driverEmail: offer.attributes?.driver_email,
          driverRating: offer.attributes?.calif_conductor,
          timestamp: offer.attributes?.createdAt || new Date().toISOString(),
        };

        if (!acc.some((item) => item.id === normalizedOffer.id)) {
          acc.push(normalizedOffer);
        }

        return acc;
      }, []);

      setOffers(normalizedOffers);

      normalizedOffers.forEach((offer) => {
        createMarkerForOffer(offer);
      });
    } catch (err) {
      console.warn('[TripView] Error cargando ofertas de viaje:', err);
      setOffers([]);
    }
  }, [createMarkerForOffer, removeAllOfferMarkers, strapiToken, strapiUrl, user?.email]);

  useEffect(() => {
    getUserData();
    loadUserPreferences();
    getTravelOffers();
  }, [getUserData, loadUserPreferences, getTravelOffers]);

  // Procesar ofertas pendientes cuando el mapa esté listo
  /*useEffect(() => {
    if (!googleMapsLoaded) return;
    if (pendingOffersRef.current.length === 0) return;
    pendingOffersRef.current.forEach((of) => createMarkerForOffer(of));
    pendingOffersRef.current = [];
  }, [googleMapsLoaded, createMarkerForOffer]);*/

  useEffect(() => {
    console.log(
      '[Pasajero] montaje: intentando conectar socket a',
      process.env.REACT_APP_SOCKET_URL,
    );
    try {
      socketRef.current = io(process.env.REACT_APP_SOCKET_URL, {
        transports: ['websocket'],
      });

      socketRef.current.on('connect', () => {
        console.log(
          '[Socket] conectado id=',
          socketRef.current.id,
          'url=',
          process.env.REACT_APP_SOCKET_URL,
        );
        if (user?.email) {
          socketRef.current.emit('register', { email: user.email });
        }
      });

      socketRef.current.on('connect_error', (err) => {
        console.warn('[Socket] connect_error:', err && (err.message || err));
      });

      socketRef.current.on('disconnect', (reason) => {
        console.warn('[Socket] disconnected:', reason);
      });

      socketRef.current.on('drivers-found', (drivers) => {
        console.log(
          '[Socket] evento drivers-found recibido. payload:',
          safeStringify(drivers, 4000),
        );
        try {
          if (Array.isArray(drivers)) {
            drivers.forEach((d) => {
              if (d.coordinates && mapRef && mapRef.current) {
                // pintar marcadores de drivers (sin infoWindow)
                try {
                  const pos = new window.google.maps.LatLng(
                    d.coordinates.lat,
                    d.coordinates.lng,
                  );
                  const marker = new window.google.maps.Marker({
                    position: pos,
                    map: mapRef.current,
                    icon: {
                      url: taxiIcon,
                      scaledSize: new window.google.maps.Size(36, 36),
                    },
                    title: d.name || 'Taxista',
                  });
                  // opcional: no guardamos estos markers en offersRef
                } catch (e) {
                  console.warn('[drivers-found] error creando marker', e);
                }
              }
            });
          }
        } catch (e) {
          console.warn('[Socket] error pintando markers drivers-found', e);
        }
        onFoundDrivers(drivers);
        setLoadingSearch(true);
      });

      socketRef.current.on('search-error', (msg) => {
        console.warn('[Socket] search-error recibido:', msg);
        setError(msg || 'Error en búsqueda via socket');
        setLoadingSearch(true);
      });

      // opcional: ack de server si envia "trip-ack" o similar
      socketRef.current.on('trip-ack', (ack) => {
        console.log('[Socket] trip-ack recibido:', ack);
      });

      socketRef.current.on('offer-accepted', async (payload) => {
        console.log('[Pasajero] offersRef:', offersRef.current, payload);
        const idx = offersRef.current.findIndex((o) => o.driver?.email === payload?.driver);
        if (idx !== -1) {
          const o = offersRef.current[idx];
          if (o.infoWindow) o.infoWindow.close();
          if (o.marker) o.marker.setMap(null);
          offersRef.current.splice(idx, 1);
          setOffers((prev) => prev.filter((p) => p.driver?.email !== payload?.driver));
        }
        await getTravelOffers();
      });

      // NUEVO: escucha del evento de oferta de viaje
      socketRef.current.on('ofertaviaje', async (payload) => {
        try {
          const coordinates =
            payload.coordinates || payload.coords || payload.location || null;
          if (
            !coordinates ||
            typeof coordinates.lat !== 'number' ||
            typeof coordinates.lng !== 'number'
          ) {
            console.warn(
              '[ofertaviaje] payload sin coordinates válidas:',
              payload,
            );
            return;
          }
          //const id = payload.meta.travelId;
          await getTravelOffers();
        } catch (e) {
          console.warn('[ofertaviaje] error procesando payload', e);
        }
      });
    } catch (e) {
      console.error('[Pasajero] no se pudo inicializar socket:', e);
      socketRef.current = null;
    }

    return () => {
      console.log(
        '[Pasajero] desmontando componente: limpiando socket listeners y markers',
      );
      try {
        if (socketRef.current) {
          socketRef.current.off('drivers-found');
          socketRef.current.off('search-error');
          socketRef.current.off('connect');
          socketRef.current.off('disconnect');
          socketRef.current.off('trip-ack');
          socketRef.current.off('ofertaviaje');
          socketRef.current.off('offer-accepted');
          socketRef.current.disconnect();
          socketRef.current = null;
        }
      } catch (e) {
        console.warn('[Pasajero] error limpiando socket:', e);
      }

      // limpiar markers/infoWindows
      try {
        offersRef.current.forEach((o) => {
          try {
            if (o.infoWindow) {
              o.infoWindow.close();
            }
            if (o.marker) {
              // quitar listeners si existen
              if (o._listeners && o._listeners.markerClickListener) {
                window.google.maps.event.removeListener(
                  o._listeners.markerClickListener,
                );
              }
              if (o._listeners && o._listeners.domReadyListener) {
                window.google.maps.event.removeListener(
                  o._listeners.domReadyListener,
                );
              }
              o.marker.setMap(null);
            }
          } catch (inner) {
            // noop
          }
        });
        offersRef.current = [];
      } catch (e) {
        console.warn('[Pasajero] error limpiando markers al desmontar', e);
      }
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []); // run once

  useEffect(() => {
    if (!navigator.geolocation) {
      console.warn('[Pasajero] geolocalización no disponible');
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        console.log('[Pasajero] geolocation success:', lat, lng);
        setFromCoordinates({ lat, lng });
        setFromMarkerPosition({ lat, lng });
        if (mapRef && mapRef.current && mapRef.current.setCenter) {
          mapRef.current.setCenter({ lat, lng });
        }
        try {
          if (window.google && window.google.maps) {
            const geocoder = new window.google.maps.Geocoder();
            geocoder.geocode({ location: { lat, lng } }, (results, status) => {
              console.log('[Pasajero] geocoder status:', status);
              if (status === 'OK' && results && results[0]) {
                setFromAddress(results[0].formatted_address);
              }
            });
          }
        } catch (e) {
          console.warn('[Pasajero] geocoder error:', e);
        }
      },
      (err) => {
        console.warn('[Pasajero] geolocation error:', err);
      },
      { maximumAge: 1000 * 60 * 5, timeout: 5000 },
    );
  }, [mapRef]);

  useEffect(() => {
    if (!mapRef || !mapRef.current || !window.google) return;
    if (!directionsServiceRef.current)
      directionsServiceRef.current = new window.google.maps.DirectionsService();
    if (!directionsRendererRef.current) {
      directionsRendererRef.current = new window.google.maps.DirectionsRenderer(
        {
          suppressMarkers: true,
          polylineOptions: {
            strokeColor: '#6d0c5dff',
            strokeWeight: 6,
            strokeOpacity: 0.95,
          },
        },
      );
      directionsRendererRef.current.setMap(mapRef.current);
    }
    return () => {
      if (directionsRendererRef.current) {
        try {
          directionsRendererRef.current.setMap(null);
        } catch (e) { }
      }
    };
  }, [mapRef, googleMapsLoaded]);

  const drawRouteOnMap = useCallback(
    (origin, destination) => {
      if (
        !window.google ||
        !directionsServiceRef.current ||
        !directionsRendererRef.current
      ) {
        console.warn('[drawRouteOnMap] google/directions no listos');
        return;
      }

      const originParam =
        typeof origin === 'string'
          ? origin
          : { lat: origin.lat, lng: origin.lng };
      const destParam =
        typeof destination === 'string'
          ? destination
          : { lat: destination.lat, lng: destination.lng };

      directionsServiceRef.current.route(
        {
          origin: originParam,
          destination: destParam,
          travelMode: window.google.maps.TravelMode.DRIVING,
        },
        (result, status) => {
          console.log('[drawRouteOnMap] Directions callback status=', status);
          if (
            status === window.google.maps.DirectionsStatus.OK ||
            status === 'OK'
          ) {
            directionsRendererRef.current.setDirections(result);
            try {
              const leg = result.routes[0].legs[0];
              const start = leg.start_location;
              const end = leg.end_location;
              if (fromMarkerRef && fromMarkerRef.current)
                fromMarkerRef.current.setPosition(start);
              if (toMarkerRef && toMarkerRef.current)
                toMarkerRef.current.setPosition(end);
              if (mapRef && mapRef.current && mapRef.current.fitBounds) {
                const bounds = new window.google.maps.LatLngBounds();
                result.routes[0].overview_path.forEach((p) => bounds.extend(p));
                mapRef.current.fitBounds(bounds);
              }
            } catch (e) {
              console.warn(
                '[drawRouteOnMap] error updating markers after route',
                e,
              );
            }
          } else {
            console.error('[drawRouteOnMap] error', status, result);
          }
        },
      );
    },
    [
      directionsRendererRef,
      directionsServiceRef,
      mapRef,
      fromMarkerRef,
      toMarkerRef,
    ],
  );

  useEffect(() => {
    if (!mapRef || !mapRef.current) return;
    if (!fromCoordinates || !toCoordinates) return;
    drawRouteOnMap(fromCoordinates, toCoordinates);
  }, [fromCoordinates, toCoordinates, drawRouteOnMap, mapRef]);

  const swapOriginDestination = useCallback(() => {
    const aAddr = fromAddress;
    const bAddr = toAddress;
    setFromAddress(bAddr);
    setToAddress(aAddr);

    const aCoords = fromCoordinates;
    const bCoords = toCoordinates;
    setFromCoordinates(bCoords);
    setToCoordinates(aCoords);

    setFromMarkerPosition(bCoords);
    setToMarkerPosition(aCoords);

    if (fromMarkerRef && fromMarkerRef.current)
      fromMarkerRef.current.setPosition(bCoords);
    if (toMarkerRef && toMarkerRef.current)
      toMarkerRef.current.setPosition(aCoords);

    if (mapRef && mapRef.current) mapRef.current.setCenter(bCoords);

    drawRouteOnMap(bCoords, aCoords);
  }, [
    fromAddress,
    toAddress,
    fromCoordinates,
    toCoordinates,
    mapRef,
    fromMarkerRef,
    toMarkerRef,
    drawRouteOnMap,
  ]);

  // BUSCAR TAXISTAS
  const buscarTaxistas = async () => {
    setError(null);
    setLoadingSearch(true);

    const userEmail = user?.email ?? null;
    const preferenceSettings = normalizePreferences(preferences);
    const payload = {
      userEmail,
      originCoordinates: fromCoordinates || null,
      destinationCoordinates: toCoordinates || null,
      originAddress: fromAddress || null,
      destinationAddress: toAddress || null,
      timestamp: new Date().toISOString(),
      settings: preferenceSettings,
    };
    console.log('[buscarTaxistas] payload:', safeStringify(payload, 2000));

    try {
      const url = `${strapiUrl}/api/configuraciones-usuarios?filters[email][$eq]=${userEmail}&populate=*`;
      const headers = {
        'Content-Type': 'application/json',
      };
      if (strapiToken) {
        headers.Authorization = `Bearer ${strapiToken}`;
      }

      const response = await fetch(url, { headers });
      if (!response.ok) {
        throw new Error("Error buscando usuario en Strapi");
      }

      const userData = await response.json();
      const userId = userData?.data?.[0]?.attributes?.usuario?.data?.id || null;
      console.log('pasajero id', userId);
      const settings = preferenceSettings;
      console.log("[AcceptTrip] configuraciones del usuario:", settings);

      // 1) Intentar POST a /test/send-trip (backend)
      const backendBase =
        process.env.REACT_APP_SOCKET_URL ||
        socketUrlToHttp(process.env.REACT_APP_SOCKET_URL) ||
        null;

      if (backendBase) {
        const url = `${backendBase.replace(/\/$/, '')}/test/send-trip`;
        try {
          const resp = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              userEmail,
              userId,
              userData: passenger || null,
              settings,
              freeTrip: Boolean(freeTrip === 'disponible'),
              originCoordinates: payload.originCoordinates,
              destinationCoordinates: payload.destinationCoordinates,
              originAdress: payload.originAddress,
              destinationAdress: payload.destinationAddress,
              broadcast: true,
            }),
          });
          const text = await resp.text().catch(() => null);
        } catch (e) {
          console.warn('[buscarTaxistas] error en POST /test/send-trip:', e);
        }
      } else {
        console.warn(
          '[buscarTaxistas] no se pudo determinar backendBase para POST /test/send-trip — revisa env vars',
        );
      }
    } catch (err) {
      console.error('[buscarTaxistas] error general:', err);
      setError(err.message || 'Error buscando taxistas');
    } finally {
      setLoadingSearch(true);
      console.log('[buscarTaxistas] finalizado (loadingSearch=false).');
    }
  };

  const centerOnOrigin = () => {
    if (mapRef && mapRef.current) {
      mapRef.current.setCenter(fromCoordinates);
      if (mapRef.current.setZoom) mapRef.current.setZoom(15);
    }
  };

  // Cerrar modal y limpiar selección
  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedOffer(null);
  };

  // Aceptar oferta: ahora llama al backend /api/aceptar-viaje y navega a /taxis/viaje/:travelId
  const acceptOffer = async () => {
    setLoadingSearch(false);
    setFromAddress(null);
    setToAddress(null);
    setFromCoordinates(null);
    setToCoordinates(null);

    if (!selectedOffer) {
      console.warn('[acceptOffer] no hay oferta seleccionada');
      return;
    }

    if (socketRef.current) {
      socketRef.current.emit('offer-accepted',
        {
          user: user?.email,
          driver: selectedOffer.driverEmail,
        }
      );
    }

    // construir backend base igual que en buscarTaxistas
    const backendBase =
      process.env.REACT_APP_SOCKET_URL || 'http://localhost:3033';

    // Evitar reentradas
    try {
      // Realiza la llamada al backend que creamos: POST /api/aceptar-viaje
      if (!backendBase) {
        console.warn(
          '[acceptOffer] backendBase no configurado. Revisa REACT_APP_SOCKET_URL o env vars.',
        );
        // procedemos con el comportamiento antiguo (cerrar modal y remover marker)
        try {
          const idx = offersRef.current.findIndex(
            (o) => o.id === selectedOffer?.id
          );
          if (idx !== -1) {
            const o = offersRef.current[idx];
            if (o.infoWindow) o.infoWindow.close();
            if (o.marker) o.marker.setMap(null);
            offersRef.current.splice(idx, 1);
            setOffers((prev) => prev.filter((p) => p.id !== selectedOffer.id));
          }
          console.log('[Pasajero] removiendo marcadores');
          removeAllOfferMarkers();
        } catch (e) {
          console.warn('[acceptOffer] error removiendo marcador', e);
        } finally {
          setSelectedOffer(null);
          setIsModalOpen(false);
        }
      }

      try {
        const headers = { 'Content-Type': 'application/json' };
        if (strapiToken) {
          headers.Authorization = `Bearer ${strapiToken}`;
        }
        const response = await fetch(
          `${strapiUrl}/api/configuraciones-usuarios?filters[email][$eq]=${user?.email}`,
          { headers }
        );
        const findData = await response.json();
        const existing = findData?.data?.[0];

        await fetch(
          `${strapiUrl}/api/configuraciones-usuarios/${existing.id}`,
          {
            method: 'PUT',
            headers,
            body: JSON.stringify({
              data: { en_viaje: true }
            }),
          }
        );

        await fetch(`${strapiUrl}/api/drivers/${selectedOffer.driverId}`, {
          method: 'PUT',
          headers,
          body: JSON.stringify({
            data: { en_viaje: true }
          }),
        });
      } catch (err) {
        console.error('[acceptOffer] error en fetch aceptar-viaje:', err);
        setError(err.message || 'Error actualizando estado de pasajero');
        return;
      }

      const url = `${backendBase.replace(/\/$/, '')}/api/aceptar-viaje`;

      // Payload: llenamos los campos que solicitaste en Strapi
      const body = {
        userEmail: user?.email ?? null,
        driverEmail: selectedOffer.driverEmail ?? null,
        origencoords: fromCoordinates ?? null,
        destinocoords: toCoordinates ?? null,
        conductorcoords: selectedOffer.coordinates ?? null,
        origendireccion: { label: fromAddress ?? '' },
        destinodireccion: { label: toAddress ?? '' },
        solicitado: new Date().toISOString(),
        travelid: selectedOffer.travelId ?? undefined,
        observaciones: selectedOffer.raw?.meta?.note ?? '',
        costo:
          typeof selectedOffer.price === 'number'
            ? selectedOffer.price
            : Number(selectedOffer.price) || null,
      };

      let respJson = null;
      try {
        const resp = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        });
        const text = await resp.text();
        try {
          respJson = JSON.parse(text);
        } catch (e) {
          respJson = { ok: resp.ok, rawText: text };
        }
        if (!resp.ok) {
          console.warn('[acceptOffer] respuesta no ok:', resp.status, respJson);
          // mostrar error y no navegar
          setError(
            respJson && respJson.error
              ? respJson.error
              : `Error server ${resp.status}`,
          );
          return;
        }
      } catch (err) {
        console.error('[acceptOffer] error en fetch aceptar-viaje:', err);
        setError(err.message || 'Error enviando aceptación al backend');
        return;
      }

      // Si llegamos aquí, la creación en Strapi fue (probablemente) exitosa
      const travelIdReturned =
        respJson && respJson.travelId
          ? respJson.travelId
          : respJson && respJson.created && respJson.created.id
            ? String(respJson.created.id)
            : null;

      // navegar a la ruta del viaje usando travelId retornado por tu endpoint
      if (travelIdReturned) {
        navigate(`/taxis/viaje/${travelIdReturned}`, { state: { isDriver: false } });
        console.log('[acceptOffer] navegando a /taxis/viaje/' + travelIdReturned);
      } else {
        // fallback: si no retornaron travelId, intenta con selectedOffer.id
        navigate(`/taxis/viaje/${selectedOffer.travelId}`, { state: { isDriver: false } });
      }
    } catch (e) {
      console.error('[acceptOffer] error general:', e);
      setError(e && e.message ? e.message : 'Error aceptando oferta');
    }
  };

  const rejectOffer = async () => {
    if (!selectedOffer) return;
    console.log('[rejectOffer] rechazando oferta id=', selectedOffer);

    try {
      const idx = offersRef.current.findIndex((o) => o.id === selectedOffer?.id);
      if (idx !== -1) {
        const o = offersRef.current[idx];
        if (o.infoWindow) o.infoWindow.close();
        if (o.marker) o.marker.setMap(null);
        offersRef.current.splice(idx, 1);
        setOffers((prev) => prev.filter((p) => p.id !== selectedOffer.id));
      }

      if (socketRef.current) {
        socketRef.current.emit('offer-rejected', {
          user: user?.email,
          driver: selectedOffer.driverEmail,
          travelId: selectedOffer.id,
        });
      }
    } catch (e) {
      console.error('[rejectOffer] error:', e);
    } finally {
      setSelectedOffer(null);
      setIsModalOpen(false);
    }
  };

  const cancelarBusqueda = async () => {
    console.log('[Pasajero] cancelando búsqueda de taxistas');
    if (socketRef.current) {
      socketRef.current.emit('cancel-search', user?.email);
    }
    removeAllOfferMarkers();
    setLoadingSearch(false);
  };

  const disabledSearch =
    loadingSearch ||
    isTraveling ||
    !fromAddress ||
    !toAddress ||
    !fromCoordinates ||
    !toCoordinates;

  // Si hay adeudos no pagados, mostrar advertencia y evitar render normal
  if (!debtsLoading && Array.isArray(debts) && debts.length > 0) {
    return (
      <div className='taxis-container'>
        <AdeudoWarning debt={debts[0]} />
      </div>
    );
  }

  return (
    <>
      <div className='taxis-container'>
        <h3
          className='trip-title'
          style={{ textAlign: 'center' }}
        >
          Buscar un viaje
        </h3>

        <div className='inputs-row improved-row'>
          <div className='input-wrap'>
            <input
              id='from-input'
              type='text'
              disabled={isTraveling}
              placeholder='Origen (tu ubicación por defecto)'
              value={fromAddress}
              onChange={(e) => setFromAddress(e.target.value)}
              className='lugar-input pasajero-origen'
            />
          </div>

          <div className='swap-wrap'>
            <button
              disabled={disabledSearch}
              title='Intercambiar origen/destino'
              onClick={swapOriginDestination}
              className='swap-button'
              aria-label='Intercambiar origen y destino'
            >
              ⇅
            </button>
          </div>

          <div className='input-wrap'>
            <input
              id='to-input'
              type='text'
              disabled={isTraveling}
              placeholder='Destino'
              value={toAddress}
              onChange={(e) => setToAddress(e.target.value)}
              className='lugar-input pasajero-destino'
            />
          </div>
        </div>

        <div className='controls-row'>
          <button
            onClick={buscarTaxistas}
            disabled={disabledSearch}
            className='buscar-taxistas formulario-pasajero pasajero-buscar'
            style={{
              flex: 2,
              padding: '12px 16px',
              backgroundColor: '#ff4081',
              color: 'white',
              border: 'none',
              borderRadius: 8
            }}
          >
            {loadingSearch ? 'Buscando taxistas...' : 'Buscar conductores'}
          </button>
          {!loadingSearch && (
            <button
              disabled={isTraveling}
              onClick={() => setPreferencesModalOpen(true)}
              className='preferencias-button formulario-pasajero pasajero-buscar'
              style={{
                flex: 1,
                padding: '12px 16px',
                backgroundColor: '#38cb64',
                color: 'white',
                border: 'none',
                borderRadius: 8
              }}
            >
              Preferencias de viaje
            </button>
          )}
          {loadingSearch && (
            <button
              onClick={cancelarBusqueda}
              className='cancelar-busqueda'
              style={{
                flex: 1,
                padding: '12px 16px',
                backgroundColor: '#5f5a5bff',
                color: 'white',
                border: 'none',
                borderRadius: 8,
                cursor: 'pointer',
                marginLeft: 8,
              }}
            >
              Cancelar
            </button>
          )}
          <button
            onClick={centerOnOrigin}
            className='center-button'
            title='Centrar en origen'
          >
            📍
          </button>
        </div>

        {freeTrip === 'disponible' && (
          <h3 style={{ textAlign: 'center', color: '#16b32b', paddingBottom: 6 }}>
            ¡Tienes un viaje gratis disponible! ¡Pide uno ahora!
          </h3>
        )}
        <FreeTripPasajero open={freeTripModalOpen} setOpen={setFreeTripModalOpen} />

        {error && (
          <div className='error-text'>
            {typeof error === 'string'
              ? error
              : error && (error.error || error.message)
                ? String(error.error || error.message)
                : JSON.stringify(error)}
          </div>
        )}

        <PreferencesModal
          open={preferencesModalOpen}
          setOpen={setPreferencesModalOpen}
          preferences={preferences}
          setPreferences={setPreferences}
          paymentLabory={paymentLabory}
          setPaymentLabory={setPaymentLabory}
          saving={preferencesSaving}
          onSavePreferences={saveUserPreferences}
        />

        <div
          className='taxis-map'
        >
          <div
            id='map'
            style={{ width: '100%', height: '100%' }}
          />
        </div>

        {/* Modal simple para oferta */}
        {isModalOpen && selectedOffer && (
          <AcceptTrip
            selectedOffer={selectedOffer}
            acceptOffer={acceptOffer}
            rejectOffer={rejectOffer}
            closeModal={closeModal}
          />
        )}
      </div>
      <BottomSheet
        initialState='collapsed'
        onStateChange={setSheetState}
        collapsedHeight={150}
        mediumHeight={350}
        fullHeight={window.innerHeight - 50}
      >
        {getSheetContent()}
      </BottomSheet>

      <Button
        variant='contained'
        onClick={handleOpenRecentTrips}
        sx={{
          position: 'fixed',
          right: 24,
          bottom: 190,
          zIndex: 2000,
          borderRadius: '999px',
          backgroundColor: '#fff200',
          color: '#111',
          boxShadow: '0 10px 24px rgba(0,0,0,0.18)',
          textTransform: 'none',
          fontWeight: 700,
          px: 2,
          py: 1,
        }}
      >
        Mis viajes
      </Button>
    </>
  );
};

export default Pasajero;