// src/index.js
import React from 'react';
import ReactDOM from 'react-dom/client';
import { Box } from "@mui/material";
import PreLoader from './components/PreLoader.jsx';
import { useNavigate } from 'react-router-dom'
import { Auth0Provider, useAuth0 } from '@auth0/auth0-react';
import { AuthProvider } from './Contexts/AuthContext';
import { RolesProvider } from './Contexts/RolesContext';
import { LocalizationProvider } from "@mui/x-date-pickers";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { BrowserRouter as Router, useLocation } from 'react-router-dom';
import { CartProvider } from './Contexts/CartContext';
import NavBar from './components/NavBar/NavBar.jsx';
import Rutas from './Routes/index.jsx';
import ScrollToTop from './components/ScrollToTop.jsx';
import Asistente from './components/Asistente/Asistente';
import { SnackbarProvider } from 'notistack';
import { NOTIF_TOAST_COMPONENTS } from './components/common/NotifToast.jsx';
import { NotificationsProvider } from './Contexts/NotificationsContext';
import './styles/index.css';

import AuthGate from './components/AuthGate.jsx';
import ErrorConfigAuth0, { auth0ConfigValida } from './components/ErrorConfigAuth0.jsx';
import { Capacitor } from '@capacitor/core';
import { FoodCartProvider } from './Contexts/FoodCartContext.jsx';

// ==============================
// GitHub Pages (u otro mount con prefijo): fallback SPA + basename
// - 404.html redirige a "<base>/?ruta=<path>"; aquí restauramos la ruta real
//   antes de que el Router lea la ubicación.
// - El basename se detecta en runtime: en GitHub Pages proyecto el app vive
//   bajo /ciudadan_app_monorepo; en dominio propio (raíz) queda sin prefijo.
//   En producción normal (www.ciudadan.org) no cambia nada.
// ==============================
(function restaurarRutaPages() {
  try {
    const q = new URLSearchParams(window.location.search).get('ruta');
    if (q) {
      const base = window.location.pathname.indexOf('/ciudadan_app_monorepo') === 0 ? '/ciudadan_app_monorepo' : '';
      window.history.replaceState({}, '', base + q);
    }
  } catch (e) { /* no-op */ }
})();
const ROUTER_BASE = window.location.pathname.indexOf('/ciudadan_app_monorepo') === 0 ? '/ciudadan_app_monorepo' : undefined;

const domain = process.env.REACT_APP_AUTH0_DOMAIN;
const clientId = process.env.REACT_APP_AUTH0_CLIENT_ID;
const audience = process.env.REACT_APP_AUTH0_AUDIENCE;
const scope = process.env.REACT_APP_AUTH0_SCOPES ?? "openid profile email offline_access";

// ==============================
// APP WRAPPER
// ==============================
const AppWrapper = () => {
  const { isLoading } = useAuth0();
  const location = useLocation();

  const hostname = window.location.hostname;
  const dominiosPrelanzamiento = [
    "taxis.ciudadan.org",
    "lideres.ciudadan.org",
    "socios.ciudadan.org",
  ];
  const isDomainPrelanzamiento = dominiosPrelanzamiento.includes(hostname);

  if (isLoading) {
    return <PreLoader />;
  }

  const isWikiRoute = location.pathname.startsWith('/wiki');
  const isPrelanzamiento = location.pathname.replace(/\/$/, '') === '/prelanzamiento' || isDomainPrelanzamiento;

  const sectionMap = {
    productos: 'market',
    contenido: 'contenidos',
    club: 'clubs',
    carrito: 'market',
    curso: 'cursos',
    referir: 'comunidad',
  };

  const pathSection = location.pathname.split('/').filter(Boolean)[0];
  const siteSection = sectionMap[pathSection] ?? pathSection ?? '';

  if (isDomainPrelanzamiento) {
    // Si viene por subdominio, forzamos la vista de Prelanzamiento
    // pero mantenemos el wrapper para consistencia de Providers si fuera necesario
    return (<><ScrollToTop /><Rutas /></>);
    // Nota: Rutas ya maneja la lógica de <Route path='/prelanzamiento' element={<Prelanzamiento />} />
    // pero para que el subdominio muestre Prelanzamiento sin que el usuario escriba /prelanzamiento,
    // necesitamos que Rutas sepa que debe renderizar Prelanzamiento.
    // Para evitar cambiar Rutas, podemos envolver el renderizado.
  }

  return (
    <Box
      id="ciudadan-app"
      sx={{
        display: "flex",
        flexDirection: "column",
        width: "100%",
        minHeight: "100dvh",
        overflowX: "clip",
      }}
    >
      {!isWikiRoute && !isPrelanzamiento && <NavBar siteSection={siteSection} />}

      <Box sx={{ flex: 1 }}>
        <Rutas />
        {!isPrelanzamiento && <AuthGate>
          <Asistente />
        </AuthGate>}
      </Box>

      {/* Separador vertical global: reserva el espacio de la barra amarilla fija
          inferior (.bottom-bar, 72px según lo que la app misma asume en
          split-action-button) para que no tape el final del contenido en
          ninguna página. En /wiki la barra no existe, así que no se inserta. */}
      {!isWikiRoute && !isPrelanzamiento && (
        <Box
          aria-hidden="true"
          sx={{
            width: "100%",
            flexShrink: 0,
            height: 88,
            pointerEvents: "none",
          }}
        />
      )}
    </Box>
  );
};

// ==============================
// AUTH0 PROVIDER (FIXED)
// ==============================
const Auth0ProviderWithNavigate = ({ children }) => {
  const navigate = useNavigate();

  const isNative = Capacitor.isNativePlatform();

  const redirectUri = isNative
    ? 'com.ciudadan.org://callback'
    : window.location.origin;

  const onRedirectCallback = (appState) => {
    navigate(appState?.returnTo || '/', { replace: true });
  };

  return (
    <Auth0Provider
      domain={domain}
      clientId={clientId}
      authorizationParams={{
        audience,
        scope,
        redirect_uri:redirectUri,
      }}
      redirectUri={redirectUri}
      cacheLocation="localstorage"
      useRefreshTokens
      onRedirectCallback={onRedirectCallback}
    >
      {children}
    </Auth0Provider>
  );
};

// ==============================
// RENDER
// ==============================
const root = ReactDOM.createRoot(document.getElementById('root'));

// Si la configuracion de Auth0 esta incompleta, no montamos Auth0Provider:
// mostraria una redireccion rota a https://authorize/?client_id=...
// En su lugar se muestra un error de configuracion accionable.
const appElement = auth0ConfigValida() ? (
  <React.StrictMode>
    <Router basename={ROUTER_BASE}>
      <ScrollToTop />
      <Auth0ProviderWithNavigate>
        <AuthProvider>
          <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="es">
            <RolesProvider>
              {/* SnackbarProvider FUERA de NotificationsProvider: éste necesita
                  consumir useSnackbar() para implementar la API de toast.
                  `Components` SOLO define las variantes `notif-*` que usa
                  useNotifications() -> look de marca (morado + verde neón). Las
                  variantes por defecto (useSnackbar legacy) siguen igual. */}
              <SnackbarProvider
                maxSnack={3}
                anchorOrigin={{ vertical: 'top', horizontal: 'right' }}
                Components={NOTIF_TOAST_COMPONENTS}
              >
                <NotificationsProvider>
                  <CartProvider>
                    <FoodCartProvider>
                      <AppWrapper />
                    </FoodCartProvider>
                  </CartProvider>
                </NotificationsProvider>
              </SnackbarProvider>
            </RolesProvider>
          </LocalizationProvider>
        </AuthProvider>
      </Auth0ProviderWithNavigate>
    </Router>
  </React.StrictMode>
) : (
  <ErrorConfigAuth0 />
);

root.render(appElement);
