// src/components/Taxis/AcceptTrip.jsx
import React, { useState, useEffect } from "react";

export default function AcceptTrip({ selectedOffer, acceptOffer, rejectOffer, closeModal }) {
  const [vehicleData, setVehicleData] = useState(null);
  const [driver, setDriver] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const strapiUrl = process.env.REACT_APP_STRAPI_URL || "";
  const strapiToken = process.env.REACT_APP_STRAPI_TOKEN || "";

  // Obtener datos del conductor desde Strapi por email
  useEffect(() => {
    if (!selectedOffer?.driverEmail) return;

    const fetchDriverData = async () => {
      setLoading(true);
      setError(null);

      try {
        if (!strapiUrl) {
          throw new Error("STRAPI URL no configurado");
        }
        const headers = {
          'Content-Type': 'application/json',
        };
        if (strapiToken) {
          headers.Authorization = `Bearer ${strapiToken}`;
        }

        // Obtener datos del conductor
        const driverEmail = selectedOffer.driverEmail;
        const url = `${strapiUrl}/api/drivers?filters[email][$eq]=${driverEmail}&populate=*`;

        const response = await fetch(url, { headers });
        if (!response.ok) {
          throw new Error('No se pudieron cargar los datos del conductor');
        }
        const data = await response.json();
        const drivers = data?.data || data || [];
        const driverData = Array.isArray(drivers) ? drivers[0] : drivers;

        if (!driverData) return null;

        const driverAttributes = driverData?.attributes;
        setDriver(driverAttributes);
        console.log('[Conductor] datos del conductor cargados:', driverData);

        // Buscar vehículos asociados al conductor
        let vehiclesData = [];
        try {
          const vehiclesUrl = `${strapiUrl}/api/carros?filters[conductoremail][$eq]=${driverEmail}&populate=*`;
          const vehiclesResponse = await fetch(vehiclesUrl, { headers });
          if (vehiclesResponse.ok) {
            const vData = await vehiclesResponse.json();
            const vehArray = vData?.data || vData || [];
            vehiclesData = Array.isArray(vehArray) ? vehArray : [vehArray];
          }
        } catch (e) {
          console.warn("[AcceptTrip] Error obteniendo vehículos:", e);
        }

        setVehicleData(vehiclesData);
      } catch (err) {
        console.error("[AcceptTrip] Error obteniendo datos del conductor:", err);
        setError(err.message || "Error cargando datos del conductor");
      } finally {
        setLoading(false);
      }
    };
    fetchDriverData();
  }, [selectedOffer?.driverEmail]);

  // Extraer información del conductor
  const vehicles = vehicleData || [];
  const vehicle = vehicles[0]?.attributes || vehicles[0] || {};

  const driverName =
    driver?.firstname && driver?.middlename && driver?.lastname
      ? `${driver.firstname} ${driver.middlename} ${driver.lastname}`
      : driver?.firstname ||
      driver?.nombre_completo ||
      driver?.username ||
      driver?.email?.split("@")[0] ||
      "Conductor";

  // Construir URL de la foto del carro
  let driverPhoto = null;
  const profilePicUrl = driver?.profile_pic?.data?.attributes?.url;
  const profilePicThumbnail = driver?.profile_pic?.data?.attributes?.formats?.thumbnail?.url;

  if (profilePicThumbnail) {
    // Usar thumbnail si disponible (más pequeño y rápido)
    driverPhoto = `${strapiUrl}${profilePicThumbnail}`;
  } else if (profilePicUrl) {
    // Fallback a la imagen original
    driverPhoto = `${strapiUrl}${profilePicUrl}`;
  }

  const vehicleLabel =
    [driver?.vehicle_brand, driver?.vehicle_model]
      .filter(Boolean)
      .join(" ") || "Vehículo no disponible";

  const vehiclePhotoFields = [
    driver?.vehicle_front_photo,
    driver?.vehicle_back_photo,
    driver?.vehicle_side_photo,
    driver?.vehicle_interior_photo,
  ];

  const vehiclePhotos = vehiclePhotoFields
    .flatMap((field) => {
      if (!field) return [];

      const data = field?.data;
      if (Array.isArray(data)) {
        return data
          .map((item) => item?.attributes)
          .filter(Boolean)
          .map((attr) => ({
            url: attr?.url ? `${strapiUrl}${attr.url}` : null,
            thumbnail: attr?.formats?.thumbnail?.url ? `${strapiUrl}${attr.formats.thumbnail.url}` : null,
          }))
          .filter((img) => img.url || img.thumbnail);
      }

      if (data?.attributes) {
        const attr = data.attributes;
        return [{
          url: attr?.url ? `${strapiUrl}${attr.url}` : null,
          thumbnail: attr?.formats?.thumbnail?.url ? `${strapiUrl}${attr.formats.thumbnail.url}` : null,
        }].filter((img) => img.url || img.thumbnail);
      }

      return [];
    })
    .filter((img, index, self) => index === self.findIndex((item) => item.url === img.url));

  const [vehiclePhotoIndex, setVehiclePhotoIndex] = useState(0);
  const vehicleSlides = [];
  for (let i = 0; i < vehiclePhotos.length; i += 2) {
    vehicleSlides.push(vehiclePhotos.slice(i, i + 2));
  }
  const currentVehicleSlide = vehicleSlides[vehiclePhotoIndex] || [];

  const isTripFree = selectedOffer?.travel?.isTripFree;

  useEffect(() => {
    setVehiclePhotoIndex(0);
  }, [selectedOffer?.driverEmail]);

  const goToPrevVehiclePhotos = () => {
    setVehiclePhotoIndex((prev) => {
      const totalSlides = Math.max(1, vehicleSlides.length);
      return prev === 0 ? totalSlides - 1 : prev - 1;
    });
  };

  const goToNextVehiclePhotos = () => {
    setVehiclePhotoIndex((prev) => {
      const totalSlides = Math.max(1, vehicleSlides.length);
      return prev === totalSlides - 1 ? 0 : prev + 1;
    });
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      style={{
        position: "fixed",
        zIndex: 99999,
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "rgba(0,0,0,0.4)",
        overflowY: 'auto'
      }}
      onClick={closeModal}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: "480px",
          height: "auto",
          background: "#fff",
          borderRadius: 10,
          padding: 18,
          boxShadow: "0 10px 30px rgba(0,0,0,0.25)",
        }}
      >
        <h3 style={{ marginTop: 0 }}>{driverName}</h3>

        {loading ? (
          <div style={{ textAlign: "center", padding: "20px 0" }}>
            <div style={{ fontSize: 14, color: "#666" }}>Cargando datos...</div>
          </div>
        ) : error ? (
          <div style={{ padding: "12px", background: "#ffebee", borderRadius: 6, marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "#c62828" }}>{error}</div>
          </div>
        ) : (
          <div style={{ display: "flex", alignItems: "center", gap: 12, margin: "12px 0" }}>
            {driverPhoto ? (
              <img
                src={driverPhoto}
                alt={driverName}
                style={{ width: 90, height: 90, borderRadius: "50%", objectFit: "cover" }}
              />
            ) : (
              <div
                style={{
                  width: 90,
                  height: 90,
                  borderRadius: "50%",
                  background: "#e8f5e9",
                  color: "#2e7d32",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontWeight: 700,
                }}
              >
                {driverName.charAt(0).toUpperCase()}
              </div>
            )}

            <div>
              <div style={{ fontSize: 20, marginTop: 5 }}>
                <strong style={{ color: '#666' }}>{driver?.license_plate}</strong>
              </div>
              <div style={{ fontSize: 16, marginTop: 5 }}>
                {vehicleLabel}
              </div>

              <div style={{ fontSize: 18, marginTop: 5, display: 'flex', justifyContent: 'space-between', width: 200 }}>
                <strong>{selectedOffer.driverRating ? `${selectedOffer.driverRating.toFixed(1)} ⭐` : '—'}</strong>
                <strong style={{
                  color: '#151bc1',
                  opacity: isTripFree && .5,
                  textDecoration: isTripFree && 'line-through'
                }}>
                  ${selectedOffer.price} MXN
                </strong>
              </div>
            </div>
          </div>
        )}
        {isTripFree &&
          <h4 style={{ textAlign: 'center', color: '#16b32b' }}>
            Este viaje es gratis
          </h4>
        }
        {vehiclePhotos.length > 0 && (
          <div style={{ marginTop: 16 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              {vehiclePhotos.length > 2 && (
                <button
                  onClick={goToPrevVehiclePhotos}
                  style={{
                    border: "none",
                    borderRadius: "50%",
                    width: 28,
                    height: 28,
                    cursor: "pointer",
                    background: "#f1f1f1",
                  }}
                >
                  ←
                </button>)}

              <div style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 8, flex: 1 }}>
                {currentVehicleSlide.map((img, index) => (
                  <img
                    key={`${img.url || img.thumbnail}-${index}`}
                    src={img.thumbnail || img.url}
                    alt={`Foto del vehículo ${vehiclePhotoIndex * 2 + index + 1}`}
                    style={{
                      width: "100%",
                      height: 100,
                      objectFit: "cover",
                      borderRadius: 8,
                      border: "1px solid #e0e0e0",
                    }}
                  />
                ))}
              </div>

              {vehiclePhotos.length > 2 && (
                <button
                  onClick={goToNextVehiclePhotos}
                  style={{
                    border: "none",
                    borderRadius: "50%",
                    width: 28,
                    height: 28,
                    cursor: "pointer",
                    background: "#f1f1f1",
                  }}
                >
                  →
                </button>)}
            </div>
            <div style={{ textAlign: "center", fontSize: 12, color: "#666", marginTop: 6 }}>
              {vehiclePhotoIndex + 1} / {Math.max(1, vehicleSlides.length)}
            </div>
          </div>
        )}

        {/* Preferencias de viaje del conductor */}
        {vehicles.length > 0 && (
          <div style={{ marginTop: 16, paddingTop: 12, borderTop: "1px solid #e0e0e0" }}>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {/* Atributos simples (azules) */}
              {vehicle?.marca && vehicle?.nombre && vehicle?.modelo && (
                <span style={{
                  display: "inline-block",
                  padding: "6px 12px",
                  background: "#e3f2fd",
                  color: "#1976d2",
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 500,
                }}>
                  {vehicle.marca} {vehicle.nombre} {vehicle.modelo}
                </span>
              )}
              {vehicle?.puertas && (
                <span style={{
                  display: "inline-block",
                  padding: "6px 12px",
                  background: "#e3f2fd",
                  color: "#1976d2",
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 500,
                }}>
                  {vehicle.puertas} puertas
                </span>
              )}

              {/* tipo_musica (array) */}
              {vehicle?.tipo_musica && Array.isArray(vehicle.tipo_musica) && vehicle.tipo_musica.length > 0 && (
                <>
                  {vehicle.tipo_musica.map((musica, index) => (
                    <span key={index} style={{
                      display: "inline-block",
                      padding: "6px 12px",
                      background: "#e3f2fd",
                      color: "#1976d2",
                      borderRadius: 20,
                      fontSize: 12,
                      fontWeight: 500,
                    }}>
                      🎵 {musica}
                    </span>
                  ))}
                </>
              )}

              {/* Enums: charla, musica */}
              {vehicle?.charla && (
                <span style={{
                  display: "inline-block",
                  padding: "6px 12px",
                  background: "#e3f2fd",
                  color: "#1976d2",
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 500,
                }}>
                  Charla: {vehicle.charla}
                </span>
              )}
              {vehicle?.musica && (
                <span style={{
                  display: "inline-block",
                  padding: "6px 12px",
                  background: "#e3f2fd",
                  color: "#1976d2",
                  borderRadius: 20,
                  fontSize: 12,
                  fontWeight: 500,
                }}>
                  Música: {vehicle.musica}
                </span>
              )}

              {/* Atributos booleanos (verde si true, rojo si false) */}
              {[
                { key: "wifi", label: "WiFi" },
                { key: "agua", label: "Agua" },
                { key: "cargador", label: "Cargador" },
                { key: "snacks", label: "Snacks" },
                { key: "portabici", label: "Portabici" },
                { key: "accesibilidad", label: "Accesibilidad" },
                { key: "mascotas", label: "Mascotas" },
                { key: "fumadores", label: "Fumadores" },
                { key: "aire_acondicionado", label: "Aire acondicionado" },
                { key: "rockola", label: "Rócola" },
                { key: "ambiente_inclusivo", label: "Ambiente inclusivo" },
                { key: "otro_genero", label: "Otro género" },
              ].map(({ key, label }) => {
                const value = vehicle?.[key];
                if (value === undefined || value === null) return null;
                const isTrue = value === true || value === 1 || value === "true" || value === "1";
                return (
                  <span key={key} style={{
                    display: "inline-block",
                    padding: "6px 12px",
                    background: isTrue ? "#c8e6c9" : "#ffcdd2",
                    color: isTrue ? "#2e7d32" : "#c62828",
                    borderRadius: 20,
                    fontSize: 12,
                    fontWeight: 500,
                  }}>
                    {label} {isTrue ? "✓" : "✗"}
                  </span>
                );
              })}
            </div>
          </div>
        )}

        <div
          style={{
            display: "flex",
            gap: 8,
            marginTop: 16
          }}
        >
          <button
            onClick={rejectOffer}
            disabled={loading}
            style={{
              flex: 1,
              padding: "8px 12px",
              borderRadius: 8,
              border: "none",
              background: loading ? "#ccc" : "#e31717",
              fontWeight: 700,
              color: "#fff",
              cursor: loading ? "default" : "pointer",
            }}
          >
            Rechazar
          </button>

          <button
            onClick={acceptOffer}
            disabled={loading}
            style={{
              flex: 1,
              padding: "8px 12px",
              borderRadius: 8,
              border: "none",
              background: loading ? "#ccc" : "#12aa12",
              fontWeight: 700,
              color: "#fff",
              cursor: loading ? "default" : "pointer",
            }}
          >
            Aceptar
          </button>
        </div>
      </div>
    </div>
  );
}
